import { test, expect } from '@playwright/test';

test.describe('Image Preview Before Submission', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload-form');
  });

  test('should display image preview when user uploads an image file', async ({ page }) => {
    // Intercept the file upload API
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Locate and upload file using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('tests/fixtures/sample-image.jpg');

    // Wait for preview to appear
    const previewContainer = page.getByRole('region', { name: /preview/i });
    await expect(previewContainer).toBeVisible();

    // Verify preview image is displayed
    const previewImage = page.getByRole('img', { name: /sample-image/i });
    await expect(previewImage).toBeVisible();

    // Verify preview image has correct dimensions
    const previewWidth = await previewImage.evaluate((el) => el.clientWidth);
    const previewHeight = await previewImage.evaluate((el) => el.clientHeight);
    expect(previewWidth).toBeGreaterThan(100);
    expect(previewHeight).toBeGreaterThan(100);

    // Verify preview image has correct source
    const previewSrc = await previewImage.evaluate((el) => el.src);
    expect(previewSrc).toContain('sample-image.jpg');

    // Verify preview image has correct alt text
    const previewAlt = await previewImage.evaluate((el) => el.alt);
    expect(previewAlt).toBe('Sample Image');

    // Verify preview container has correct title
    const previewTitle = await previewContainer.getByText(/preview/i);
    await expect(previewTitle).toBeVisible();
  });

  test('should display error message when uploading an invalid file type', async ({ page }) => {
    // Intercept the file upload API
    await page.route('**/api/upload', (route) => {
      route.abort('Failed to upload');
    });

    // Locate and upload invalid file using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('tests/fixtures/invalid-file.txt');

    // Wait for error message to appear
    const errorMessage = page.getByText(/Only image files are allowed/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message is displayed
    const errorContainer = page.getByRole('region', { name: /error/i });
    await expect(errorContainer).toBeVisible();

    // Verify error message contains correct text
    await expect(errorMessage).toContainText('Only image files are allowed');

    // Verify preview container is not visible
    const previewContainer = page.getByRole('region', { name: /preview/i });
    await expect(previewContainer).not.toBeVisible();
  });
});
